import{G as e,W as t,n,rt as r}from"./chunks/framework.CHX_0itn.js";var i=JSON.parse(`{"title":"TTL 检测机制与原理","description":"","frontmatter":{"title":"TTL 检测机制与原理"},"headers":[],"relativePath":"traditional/TTL.md","filePath":"traditional/TTL.md"}`),a={name:`traditional/TTL.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="⏳-ttl-检测原理" tabindex="-1">⏳ TTL 检测原理 <a class="header-anchor" href="#⏳-ttl-检测原理" aria-label="Permalink to “⏳ TTL 检测原理”">​</a></h1><p>在校园网多设备检测的各种技术手段中，<strong>TTL 检测</strong>是成本最低、应用最广的。</p><h2 id="❓-什么是-ttl" tabindex="-1">❓ 什么是 TTL <a class="header-anchor" href="#❓-什么是-ttl" aria-label="Permalink to “❓ 什么是 TTL”">​</a></h2><p>TTL（Time To Live） 是 IPv4 数据包首部中的一个 8 位（bit） 字段，它的主要作用是防止数据包在网络中因路由环路而无休止地循环传输。</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>数据包每经过一台三层路由转发，TTL都会 -1 ，当为 0 时，路由器就会丢弃该数据包并返回错误信息</p></div><h3 id="📃-常见操作系统的默认初始-ttl-值" tabindex="-1">📃 常见操作系统的默认初始 TTL 值 <a class="header-anchor" href="#📃-常见操作系统的默认初始-ttl-值" aria-label="Permalink to “📃 常见操作系统的默认初始 TTL 值”">​</a></h3><p>不同操作系统发出的数据包，其初始 TTL 设定并不完全相同：</p><table tabindex="0"><thead><tr><th style="text-align:left;">操作系统类型</th><th style="text-align:left;">默认初始 TTL 值</th><th style="text-align:left;">常见网络设备 / 系统示例</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Linux / Android</strong></td><td style="text-align:left;"><strong>64</strong></td><td style="text-align:left;">Android 手机、OpenWrt 路由器、大部分 Linux 发行版</td></tr><tr><td style="text-align:left;"><strong>iOS / macOS</strong></td><td style="text-align:left;"><strong>64</strong></td><td style="text-align:left;">iPhone、iPad、MacBook</td></tr><tr><td style="text-align:left;"><strong>Windows</strong></td><td style="text-align:left;"><strong>128</strong></td><td style="text-align:left;">Windows 10/11、Windows Server</td></tr><tr><td style="text-align:left;"><strong>Unix / 部分网络设备</strong></td><td style="text-align:left;"><strong>255</strong></td><td style="text-align:left;">Cisco 路由器、Solaris 系统等</td></tr></tbody></table><h2 id="🔬-校园网检测-ttl-的原理" tabindex="-1">🔬 校园网检测 TTL 的原理 <a class="header-anchor" href="#🔬-校园网检测-ttl-的原理" aria-label="Permalink to “🔬 校园网检测 TTL 的原理”">​</a></h2><p>校园网网关在出口处对所有 IPv4 数据包首部的 <code>TTL</code> 字段进行实时校验。</p><h3 id="_1-正常直连-未挂载路由器" tabindex="-1">1. 正常直连（未挂载路由器） <a class="header-anchor" href="#_1-正常直连-未挂载路由器" aria-label="Permalink to “1. 正常直连（未挂载路由器）”">​</a></h3><p>当单台设备直接连接校园网时，数据包未经中间路由转发，网关接收到的 TTL 保持为系统默认初始值。</p><table tabindex="0"><thead><tr><th style="text-align:left;">设备类型</th><th style="text-align:left;">请求流量类型</th><th style="text-align:left;">抓取的 TTL 特征</th><th style="text-align:left;">校园网网关判定</th></tr></thead><tbody><tr><td style="text-align:left;">Windows 电脑</td><td style="text-align:left;">IPv4 数据包</td><td style="text-align:left;">TTL = <code>128</code></td><td style="text-align:left;">唯一设备（Windows）</td></tr><tr><td style="text-align:left;">Android 手机</td><td style="text-align:left;">IPv4 数据包</td><td style="text-align:left;">TTL = <code>64</code></td><td style="text-align:left;">唯一设备（Android/iOS）</td></tr></tbody></table><hr><h3 id="_2-挂载路由器-经过路由-nat-转发" tabindex="-1">2. 挂载路由器（经过路由 NAT 转发） <a class="header-anchor" href="#_2-挂载路由器-经过路由-nat-转发" aria-label="Permalink to “2. 挂载路由器（经过路由 NAT 转发）”">​</a></h3><p>宿舍接入路由器后，设备的流量经过路由转发时 <code>TTL</code> 均被强制 <code>-1</code> 。</p><table tabindex="0"><thead><tr><th style="text-align:left;">下挂设备组合</th><th style="text-align:left;">抓取的 TTL 特征</th><th style="text-align:left;">校园网网关判定</th></tr></thead><tbody><tr><td style="text-align:left;">Windows 电脑</td><td style="text-align:left;">TTL = <code>127</code></td><td style="text-align:left;">⚠️ <strong>封禁或增加封禁概率</strong></td></tr><tr><td style="text-align:left;">Windows 电脑 + Android 手机</td><td style="text-align:left;">TTL = <code>127</code> 与 <code>63</code> 混合出现</td><td style="text-align:left;">⚠️ <strong>封禁或增加封禁概率</strong></td></tr></tbody></table>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};